<script>
document.addEventListener('DOMContentLoaded', () => {
    const form = document.querySelector('[data-leave-form]'); if (!form) return;
    const list = form.querySelector('[data-date-list]'); const addButton = form.querySelector('[data-add-leave-date]');
    const documentInput = form.querySelector('[data-supporting-document]'); const reasonInput = form.querySelector('[name="reason"]');
    const dateError = form.querySelector('[data-date-error]'); const documentError = form.querySelector('[data-document-error]'); const reasonError = form.querySelector('[data-reason-error]');
    const remaining = Number(form.dataset.remainingLeave || 0); const type = form.querySelector('input[name="type"]').value; const hasPreviousDocument = @json($hasSupportingDocument);
    const dateInputs = () => [...list.querySelectorAll('input[data-workspace-date-enhanced]')];
    const setError = (input, message) => input?.classList.toggle('is-invalid', Boolean(message));
    const setMessage = (element, message) => { element.textContent = message || ''; element.hidden = !message; element.classList.toggle('d-block', Boolean(message)); };
    const refresh = () => dateInputs().forEach((input, index) => { const row = input.closest('[data-date-row]'); row.querySelector('.workspace-leave-date-index').textContent = index + 1; row.querySelector('[data-remove-leave-date]').disabled = list.children.length === 1; input.setAttribute('aria-label', `Tanggal pengajuan ${index + 1}`); });
    const validate = () => { let firstInvalid = null; const fail = (input, message, messageElement = null) => { setError(input, message); if (messageElement) setMessage(messageElement, message); if (!firstInvalid) firstInvalid = input; }; const dates = dateInputs(); const values = dates.map((input) => input.value).filter(Boolean); const reason = reasonInput.value.trim(); dates.forEach((input) => setError(input, '')); setMessage(dateError, ''); setError(documentInput, ''); setMessage(documentError, ''); setError(reasonInput, ''); setMessage(reasonError, ''); const emptyDate = dates.find((input) => !input.value); if (emptyDate) fail(emptyDate, 'Semua baris tanggal wajib diisi.', dateError); else if (values.length === 0) fail(dates[0], 'Pilih minimal satu tanggal pengajuan.', dateError); else if (values.length !== new Set(values).size) fail(dates[0], 'Tanggal pengajuan tidak boleh duplikat.', dateError); else if (type === 'leave' && values.length > remaining) fail(dates[remaining] || dates[0], `Jumlah tanggal tidak boleh melebihi sisa kuota (${remaining} hari).`, dateError); if (!reason) fail(reasonInput, 'Alasan pengajuan wajib diisi.', reasonError); const file = documentInput.files[0]; if (type === 'sick' && !file && !hasPreviousDocument) fail(documentInput, 'Surat pendukung wajib tersedia untuk pengajuan sakit.', documentError); if (file && (!/\.(pdf|jpe?g|png)$/i.test(file.name) || file.size > 10 * 1024 * 1024)) fail(documentInput, 'Dokumen harus PDF/JPG/PNG dan maksimal 10 MB.', documentError); return firstInvalid; };
    addButton.addEventListener('click', () => { const row = list.querySelector('[data-date-row]').cloneNode(true); row.querySelector('input[data-workspace-date-enhanced]').value = ''; row.querySelector('input[data-workspace-date-value]').value = ''; list.append(row); refresh(); });
    list.addEventListener('click', (event) => { if (event.target.matches('[data-remove-leave-date]') && list.children.length > 1) { event.target.closest('[data-date-row]').remove(); refresh(); } });
    form.addEventListener('input', (event) => { if (event.target.matches('input[data-workspace-date-enhanced], [name="reason"], [data-supporting-document]')) validate(); });
    form.addEventListener('submit', (event) => { const firstInvalid = validate(); if (firstInvalid) { event.preventDefault(); firstInvalid.focus({ preventScroll: true }); firstInvalid.scrollIntoView({ behavior: 'smooth', block: 'center' }); } }); refresh();
});
</script>
